import type { ThemeDef } from '../nodes';
import { aliasTarget, cssVarName } from '../resolve';
import {
  type ResolvedToken,
  type ResolvedTokens,
  type ShadowLayer,
  TIERS,
  type TokenValue,
} from '../types';

export const GENERATED_HEADER =
  'Generated by scripts/build-design-tokens.mjs from libs/design-tokens/nodes. Do not edit.';

const GENERIC_FAMILIES = new Set([
  'serif',
  'sans-serif',
  'monospace',
  'cursive',
  'fantasy',
  'system-ui',
  'ui-serif',
  'ui-sans-serif',
  'ui-monospace',
  'ui-rounded',
  'emoji',
  'math',
  'fangsong',
  '-apple-system',
  'BlinkMacSystemFont',
]);

/** A literal token value as CSS text (no aliases). */
export function cssLiteral(type: ResolvedToken['type'], value: TokenValue): string {
  if (type === 'fontFamily') {
    const families = Array.isArray(value) ? value : [value];
    return families
      .map((f) => (GENERIC_FAMILIES.has(String(f)) ? String(f) : `"${String(f)}"`))
      .join(', ');
  }
  if (type === 'cubicBezier' && Array.isArray(value)) return `cubic-bezier(${value.join(', ')})`;
  if (type === 'shadow') return cssShadow(value as readonly ShadowLayer[], (color) => color);
  return String(value);
}

/** Shadow layers as CSS, comma-separated; `color` writes each layer's color. */
function cssShadow(layers: readonly ShadowLayer[], color: (value: string) => string): string {
  return layers
    .map((l) =>
      [l.inset ? 'inset' : '', l.offsetX, l.offsetY, l.blur, l.spread ?? '', color(l.color)]
        .filter(Boolean)
        .join(' '),
    )
    .join(', ');
}

/** A token's CSS value: aliases stay live as `var(--…)`, literals are written out. */
export function cssValue(token: ResolvedToken): string {
  if (token.alias !== undefined) return `var(${cssVarName(token.alias)})`;
  if (token.type === 'shadow') {
    // Layer colors stay live too, so a theme that overrides a shadow color moves the shadow.
    return cssShadow(token.value as readonly ShadowLayer[], (color) => {
      const target = aliasTarget(color);
      return target === undefined ? color : `var(${cssVarName(target)})`;
    });
  }
  return cssLiteral(token.type, token.value);
}

/** Selectors a theme's block is scoped to. */
export function themeSelectors(theme: ThemeDef): string[] {
  const scoped = `[data-theme="${theme.node}"]`;
  return theme.isDefault ? [':root', scoped] : [scoped];
}

/** The repo's formatter width (biome.json); the generated CSS is linted like the rest. */
const LINE_WIDTH = 100;

/** One declaration, its value on the next line when it won't fit, as the formatter prints it. */
function declaration(token: ResolvedToken): string {
  const line = `  ${cssVarName(token.id)}: ${cssValue(token)};`;
  return line.length <= LINE_WIDTH ? line : `  ${cssVarName(token.id)}:\n    ${cssValue(token)};`;
}

/** One `selector { --token: value; }` block, grouped by tier. */
export function cssBlock(selectors: string[], tokens: ResolvedTokens): string {
  const sections = TIERS.map((tier) => {
    const lines = [...tokens.values()].filter((t) => t.tier === tier).map(declaration);
    return lines.length ? [`  /* ${tier} */`, ...lines].join('\n') : '';
  }).filter(Boolean);
  return `${selectors.join(',\n')} {\n${sections.join('\n\n')}\n}\n`;
}

/** A theme stylesheet with the generated-file header. */
export function themeCss(theme: ThemeDef, chain: string[], tokens: ResolvedTokens): string {
  return `/* ${GENERATED_HEADER} */\n/* ${theme.node}: ${chain.join(' → ')} */\n\n${cssBlock(themeSelectors(theme), tokens)}`;
}
